macro_rules! deps {
    () => {
        Immutable!();
        KnownLayout!();
        IntoBytes!();
        FromBytes!();
        Unaligned!();
    };
}

macro_rules! Unalign {
    () => {
        deps!();
        # [doc = " A type with no alignment requirement."] # [doc = ""] # [doc = " An `Unalign` wraps a `T`, removing any alignment requirement. `Unalign<T>`"] # [doc = " has the same size and bit validity as `T`, but not necessarily the same"] # [doc = " alignment [or ABI]. This is useful if a type with an alignment requirement"] # [doc = " needs to be read from a chunk of memory which provides no alignment"] # [doc = " guarantees."] # [doc = ""] # [doc = " Since `Unalign` has no alignment requirement, the inner `T` may not be"] # [doc = " properly aligned in memory. There are five ways to access the inner `T`:"] # [doc = " - by value, using [`get`] or [`into_inner`]"] # [doc = " - by reference inside of a callback, using [`update`]"] # [doc = " - fallibly by reference, using [`try_deref`] or [`try_deref_mut`]; these can"] # [doc = "   fail if the `Unalign` does not satisfy `T`'s alignment requirement at"] # [doc = "   runtime"] # [doc = " - unsafely by reference, using [`deref_unchecked`] or"] # [doc = "   [`deref_mut_unchecked`]; it is the caller's responsibility to ensure that"] # [doc = "   the `Unalign` satisfies `T`'s alignment requirement"] # [doc = " - (where `T: Unaligned`) infallibly by reference, using [`Deref::deref`] or"] # [doc = "   [`DerefMut::deref_mut`]"] # [doc = ""] # [doc = " [or ABI]: https://github.com/google/zerocopy/issues/164"] # [doc = " [`get`]: Unalign::get"] # [doc = " [`into_inner`]: Unalign::into_inner"] # [doc = " [`update`]: Unalign::update"] # [doc = " [`try_deref`]: Unalign::try_deref"] # [doc = " [`try_deref_mut`]: Unalign::try_deref_mut"] # [doc = " [`deref_unchecked`]: Unalign::deref_unchecked"] # [doc = " [`deref_mut_unchecked`]: Unalign::deref_mut_unchecked"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " In this example, we need `EthernetFrame` to have no alignment requirement -"] # [doc = " and thus implement [`Unaligned`]. `EtherType` is `#[repr(u16)]` and so"] # [doc = " cannot implement `Unaligned`. We use `Unalign` to relax `EtherType`'s"] # [doc = " alignment requirement so that `EthernetFrame` has no alignment requirement"] # [doc = " and can implement `Unaligned`."] # [doc = ""] # [doc = " ```rust"] # [doc = " use zerocopy::*;"] # [doc = " # use zerocopy_derive::*;"] # [doc = " # #[derive(FromBytes, KnownLayout, Immutable, Unaligned)] #[repr(C)] struct Mac([u8; 6]);"] # [doc = ""] # [doc = " # #[derive(PartialEq, Copy, Clone, Debug)]"] # [doc = " #[derive(TryFromBytes, KnownLayout, Immutable)]"] # [doc = " #[repr(u16)]"] # [doc = " enum EtherType {"] # [doc = "     Ipv4 = 0x0800u16.to_be(),"] # [doc = "     Arp = 0x0806u16.to_be(),"] # [doc = "     Ipv6 = 0x86DDu16.to_be(),"] # [doc = "     # /*"] # [doc = "     ..."] # [doc = "     # */"] # [doc = " }"] # [doc = ""] # [doc = " #[derive(TryFromBytes, KnownLayout, Immutable, Unaligned)]"] # [doc = " #[repr(C)]"] # [doc = " struct EthernetFrame {"] # [doc = "     src: Mac,"] # [doc = "     dst: Mac,"] # [doc = "     ethertype: Unalign<EtherType>,"] # [doc = "     payload: [u8],"] # [doc = " }"] # [doc = ""] # [doc = " let bytes = &["] # [doc = "     # 0, 1, 2, 3, 4, 5,"] # [doc = "     # 6, 7, 8, 9, 10, 11,"] # [doc = "     # /*"] # [doc = "     ..."] # [doc = "     # */"] # [doc = "     0x86, 0xDD,            // EtherType"] # [doc = "     0xDE, 0xAD, 0xBE, 0xEF // Payload"] # [doc = " ][..];"] # [doc = ""] # [doc = " // PANICS: Guaranteed not to panic because `bytes` is of the right"] # [doc = " // length, has the right contents, and `EthernetFrame` has no"] # [doc = " // alignment requirement."] # [doc = " let packet = EthernetFrame::try_ref_from_bytes(&bytes).unwrap();"] # [doc = ""] # [doc = " assert_eq!(packet.ethertype.get(), EtherType::Ipv6);"] # [doc = " assert_eq!(packet.payload, [0xDE, 0xAD, 0xBE, 0xEF]);"] # [doc = " ```"] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " `Unalign<T>` is guaranteed to have the same size and bit validity as `T`,"] # [doc = " and to have [`UnsafeCell`]s covering the same byte ranges as `T`."] # [doc = " `Unalign<T>` is guaranteed to have alignment 1."] # [allow (missing_debug_implementations)] # [derive (Default , Copy)] # [cfg_attr (any (feature = "derive" , test) , derive (Immutable , FromBytes , IntoBytes , Unaligned))] # [repr (C , packed)] pub struct Unalign < T > (T) ;
    };
}

Unalign!();